package com.cinenest.payments.internal;
import com.cinenest.identity.ScopedAuthorization;import com.cinenest.pricing.BankQuotation;import com.cinenest.verification.BankEligibility;import com.cinenest.booking.SyntheticBooking;
import java.time.*;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
@Service
class LedgerService {
 private final LedgerRepository db;private final BankRepository bank;private final ScopedAuthorization auth;private final BankQuotation quotes;private final BankEligibility eligibility;private final SyntheticBooking bookings;private final SyntheticCreditSource source;private final TransactionTemplate tx;
 LedgerService(LedgerRepository db,BankRepository bank,ScopedAuthorization auth,BankQuotation quotes,BankEligibility eligibility,SyntheticBooking bookings,SyntheticCreditSource source,PlatformTransactionManager manager){this.db=db;this.bank=bank;this.auth=auth;this.quotes=quotes;this.eligibility=eligibility;this.bookings=bookings;this.source=source;tx=new TransactionTemplate(manager);}
 void configured(){source.configured();}
 void reconcile(){source.maintenance();tx.executeWithoutResult(s->{var rows=db.overdueExceptions(Map.of("v",source.venue()));for(var e:rows){db.escalateException(Map.of("id",e.get("exception_id")));bank.audit(null,(UUID)e.get("request_id"),"FINANCIAL_OVERDUE","SYNTHETIC_STAFF_REQUIRED");}});}

 static Instant instant(Object v){if(v instanceof java.sql.Timestamp t)return t.toInstant();if(v instanceof OffsetDateTime t)return t.toInstant();throw new IllegalStateException("Invalid database timestamp");}
 static UUID id(Object x){return BankService.id(x);}static long n(Object x){return BankService.number(x);}static String text(Map<String,Object>b,String k){Object v=b.get(k);if(!(v instanceof String s)||s.isBlank()||s.length()>160||s.chars().anyMatch(Character::isISOControl))throw new BankFailure(400,"Bounded reason/reference required");return s;}
 void permit(UUID a,UUID v,String p){source.configured();if(!auth.permits(a,v,p,true))throw new BankFailure(403,"Current synthetic venue capability required");}

 Map<String,Object> credit(UUID v,UUID c,boolean lock){return db.credit(Map.of("c",c,"v",v),lock);}

 long allocatedCredit(UUID c){return db.allocatedCredit(Map.of("c",c));}
 long allocatedRequest(UUID r){return db.allocatedRequest(Map.of("r",r));}
 boolean disputed(UUID c){return !db.adjustments(Map.of("c",c)).isEmpty();}
 Map<String,Object> creditView(UUID v,UUID id){var c=credit(v,id,false);long used=allocatedCredit(id);var out=new LinkedHashMap<String,Object>();out.put("id",id);out.put("matches",db.matchedRequest(Map.of("c",id)).stream().map(m->Map.of("requestId",m.get("request_id"),"requestRevision",m.get("revision"),"outstandingMinor",Math.max(0,n(m.get("amount_minor"))-allocatedRequest((UUID)m.get("request_id"))))).toList());out.put("amountMinor",c.get("amount_minor"));out.put("currency","LKR");out.put("allocatedMinor",used);out.put("availableMinor",disputed(id)?0:Math.subtractExact(Math.subtractExact(((Number)c.get("amount_minor")).longValue(),used),db.refundCommitted(Map.of("c",id))));out.put("disputed",disputed(id));out.put("creditedAt",instant(c.get("credited_at")).toString());out.put("sourceKind",c.get("source_kind"));out.put("syntheticFundingStatus",disputed(id)?"DISPUTED":"SIMULATED_VERIFIED");out.put("fixtureKey",c.get("fixture_key"));out.put("manifestHash",c.get("manifest_hash"));out.put("verifiedAt",instant(c.get("verified_at")).toString());out.put("corrections",db.correctionHistory(Map.of("c",id)));out.put("synthetic",true);out.put("paymentVerified",false);out.put("label","SYNTHETIC TEST — NO REAL MONEY");return out;}
 void financialException(UUID venue,UUID request,UUID credit,String kind){var p=new HashMap<String,Object>();p.put("id",UUID.randomUUID());p.put("v",venue);p.put("r",request);p.put("c",credit);p.put("kind",kind);p.put("seconds",source.resolutionSeconds());db.createException(p);if(request!=null)bank.work(request,null,"FINANCIAL",bank.now());}
 Map<String,Object> command(UUID a,UUID v,UUID target,String action,Map<String,Object>b){
  String capability=switch(action){case "CREDIT"->"bank.synthetic.credit.verify";case "MATCH","ALLOCATE"->"bank.synthetic.allocate";case "ACTION"->"bank.synthetic.resolve";case "CORRECT"->"bank.synthetic.correct.request";case "APPROVE"->"bank.synthetic.correct.approve";default->throw new BankFailure(400,"Unsupported operation");};
  switch(action){case "CREDIT"->BankService.keys(b,"fixtureKey","commandKey","expectedRevision","reason");case "MATCH"->BankService.keys(b,"requestId","commandKey","expectedRevision","reason");case "ALLOCATE"->BankService.keys(b,"creditId","amountMinor","commandKey","expectedRevision","reason");case "ACTION"->BankService.keys(b,"action","assignedTo","commandKey","expectedRevision","reason");case "CORRECT"->BankService.keys(b,"sourceKey","commandKey","expectedRevision","reason");case "APPROVE"->BankService.keys(b,"commandKey","expectedRevision","reason");}
  UUID key=id(b.get("commandKey"));String reason=text(b,"reason"),hash=BankPolicy.commandHash("LEDGER:"+v+":"+target+":"+action,b);n(b.get("expectedRevision"));
  try{return tx.execute(status->{var principals=new TreeSet<UUID>();principals.add(a);
   UUID owner=null;if(action.equals("MATCH")||action.equals("ALLOCATE")){UUID rid=action.equals("MATCH")?id(b.get("requestId")):target;var discovered=bank.request(rid,false);if(discovered.isPresent()&&discovered.get().venue().equals(v)){owner=discovered.get().owner();principals.add(owner);}}
   else if(action.equals("CORRECT")||action.equals("APPROVE")){UUID cid=action.equals("CORRECT")?target:(UUID)db.adjustmentCredit(Map.of("id",target)).get("credit_id");var linked=db.matchedOwner(Map.of("c",cid));if(!linked.isEmpty()){owner=(UUID)linked.getFirst().get("owner_id");principals.add(owner);if(owner.equals(a))throw new BankFailure(403,"Own financial correction denied");}}
   for(UUID principal:principals)if(!auth.eligible(principal,true))throw new BankFailure(403,"Current synthetic account required");
   permit(a,v,capability);var replay=bank.command(a,key,hash);if(replay.isPresent())return replay.get();Map<String,Object> result;
   if(action.equals("CREDIT")){
    if(n(b.get("expectedRevision"))!=0)throw new BankFailure(409,"Source revision changed");var f=source.fixture(text(b,"fixtureKey"));if(!f.venue().equals(v)||f.credited().isAfter(bank.now()))throw new BankFailure(400,"Wrong source venue/time");UUID sid=UUID.nameUUIDFromBytes(f.hash().getBytes(java.nio.charset.StandardCharsets.UTF_8)),cid=UUID.randomUUID();
    db.sourceRevision(Map.of("id",sid,"key",f.key(),"hash",f.hash()));
    db.recordCredit(Map.of("id",cid,"source",sid,"v",v,"account",f.account(),"movement",f.movement(),"kind",f.kind(),"amount",f.amount(),"at",f.credited().atOffset(ZoneOffset.UTC)));
    db.verifyCredit(Map.of("id",UUID.randomUUID(),"c",cid,"a",a,"reason",reason));financialException(v,null,cid,"UNMATCHED");result=creditView(v,cid);
   }else if(action.equals("MATCH")||action.equals("ALLOCATE")){
    UUID requestId=action.equals("MATCH")?id(b.get("requestId")):target;var r=bank.request(requestId,true).orElseThrow(()->new BankFailure(404,"Request not found"));if(!r.venue().equals(v)||r.owner().equals(a))throw new BankFailure(403,"Own or unrelated request denied");
    if(r.revision()!=n(b.get("expectedRevision")))throw new BankFailure(409,"Request changed");UUID cid=action.equals("MATCH")?target:id(b.get("creditId"));var c=credit(v,cid,true);
    if(c.get("verifier_id").equals(a)||c.get("verifier_id").equals(r.owner())||disputed(cid))throw new BankFailure(403,"Independent unconflicted verifier/allocator required");
    if(action.equals("MATCH")){
     db.matchCredit(Map.of("c",cid,"r",r.id(),"a",a,"reason",reason));db.resolveUnmatched(Map.of("c",cid));bank.transition(r.id(),r.state(),r.review());result=creditView(v,cid);
    }else{
     if(!r.expires().isAfter(bank.now())||Set.of("EXPIRED","CANCELLED").contains(r.state()))throw new BankFailure(409,"Request expired; funds retained");
     var q=db.acceptedRequestTerms(Map.of("r",r.id()));var facts=quotes.requestBound(r.owner(),r.quote(),n(q.get("quote_revision")),q.get("quote_hash").toString()).orElseThrow(()->new BankFailure(409,"Accepted terms changed"));
     if(!bookings.entitled(r.owner(),r.hold())||!auth.eligible(r.owner(),false)||!eligibility.eligible(r.owner(),r.quote(),v)||!r.expires().isAfter(bank.now()))throw new BankFailure(409,"Current booker eligibility required");
     long amount=n(b.get("amountMinor")),due=Long.parseLong(r.amount()),before=allocatedRequest(r.id());if(amount<=0||amount>Math.subtractExact(due,before)||amount>Math.subtractExact(Math.subtractExact(n(c.get("amount_minor")),allocatedCredit(cid)),db.refundCommitted(Map.of("c",cid))))throw new BankFailure(409,"Allocation exceeds available credit or outstanding");
     if(instant(c.get("credited_at")).isAfter(r.expires()))throw new BankFailure(409,"Late synthetic credit requires resolution");
     db.allocate(Map.of("id",UUID.randomUUID(),"c",cid,"r",r.id(),"amount",amount,"a",a,"key",key));
     UUID booking=null;if(Math.addExact(before,amount)==due)booking=bookings.confirm(new SyntheticBooking.Funding(r.id(),a,r.owner(),v,r.hold(),r.quote(),facts.revision(),facts.hash(),due,"LKR",facts.snapshot(),key));
     bank.transition(r.id(),r.state(),r.review());if(booking==null)financialException(v,r.id(),null,"PARTIAL");else db.resolvePartial(Map.of("r",r.id()));if(n(c.get("amount_minor"))>allocatedCredit(cid))financialException(v,r.id(),cid,"EXCESS");result=customerStatus(r.id());
    }
   }else if(action.equals("CORRECT")){
    var c=credit(v,target,true);if(db.matchedOwner(Map.of("c",target)).stream().anyMatch(m->m.get("owner_id").equals(a)))throw new BankFailure(403,"Own financial correction denied");if(n(b.get("expectedRevision"))!=0)throw new BankFailure(403,"Independent correction proposer required");String sk=text(b,"sourceKey");if(!sk.equals("SYNTHETIC-REVERSAL-"+target))throw new BankFailure(400,"Controlled synthetic reversal source required");
    UUID adj=UUID.randomUUID();db.proposeCorrection(Map.of("id",adj,"c",target,"key",sk,"a",a,"reason",reason));financialException(v,null,target,"DISPUTED");result=Map.of("adjustmentId",adj,"state","PENDING_INDEPENDENT_APPROVAL","synthetic",true);
   }else if(action.equals("APPROVE")){
    var adj=db.lockCorrection(Map.of("id",target,"v",v));UUID cid=(UUID)adj.get("credit_id");if(adj.get("proposer_id").equals(a)||adj.get("approver_id")!=null||n(b.get("expectedRevision"))!=0)throw new BankFailure(403,"Independent current correction decision required");
    var match=db.matchedRequest(Map.of("c",cid));if(!match.isEmpty()&&match.getFirst().get("owner_id").equals(a))throw new BankFailure(403,"Own financial correction denied");
    db.approveCorrection(Map.of("a",a,"id",target));financialException(v,match.isEmpty()?null:(UUID)match.getFirst().get("request_id"),cid,"SOURCE_REVERSED");result=creditView(v,cid);
   }else{
    var e=db.lockException(Map.of("id",target,"v",v));if(n(e.get("revision"))!=n(b.get("expectedRevision")))throw new BankFailure(409,"Exception changed");String choice=text(b,"action");if(!Set.of("ASSIGN","HANDOVER","ESCALATE").contains(choice))throw new BankFailure(400,"Resolution action required");UUID assignee=choice.equals("ESCALATE")?a:id(b.get("assignedTo"));if(!auth.permits(assignee,v,"bank.synthetic.resolve",false)||choice.equals("HANDOVER")&&assignee.equals(a))throw new BankFailure(403,"Eligible independent handover required");db.assignException(Map.of("a",assignee,"s",choice.equals("ESCALATE")?"ESCALATED":"OPEN","id",target));result=exceptionView(v,target);
   }
   financialAudit(a,v,target!=null?target:result.containsKey("id")?id(result.get("id")):null,"LEDGER_"+action,reason,key);bank.command(a,key,hash,result);return result;
  });}catch(com.cinenest.booking.BankRequestHolds.Rejected|BankFailure|org.springframework.dao.DataAccessException failure){if(action.equals("ALLOCATE")){try{tx.executeWithoutResult(s->{permit(a,v,capability);var r=bank.request(target,true).orElse(null);if(r!=null&&r.venue().equals(v)&&!r.owner().equals(a)){financialException(v,target,null,"BOOKING_RESOLUTION");bank.audit(a,target,"CONFIRM_FAILED","FUNDS_RETAINED");}});}catch(RuntimeException unavailable){failure.addSuppressed(unavailable);}}throw failure;}
 }
 void financialAudit(UUID a,UUID v,UUID resource,String action,String reason,UUID correlation){var p=new HashMap<String,Object>();p.put("id",UUID.randomUUID());p.put("a",a);p.put("v",v);p.put("resource",resource);p.put("action",action);p.put("reason",reason);p.put("key",correlation);db.audit(p);}
 Map<String,Object> customerStatus(UUID request){var r=bank.request(request,false).orElseThrow();long total=allocatedRequest(request);long shortfall=db.fundingShortfall(Map.of("r",request));var booking=bookings.forRequest(request);boolean reversed=!db.requestDisputes(Map.of("r",request)).isEmpty();var out=new LinkedHashMap<String,Object>();out.put("requestRevision",r.revision());out.put("allocatedMinor",total);out.put("outstandingMinor",Math.max(0,Math.addExact(Long.parseLong(r.amount())-total,shortfall)));out.put("fundingShortfallMinor",shortfall);out.put("syntheticFundingStatus",reversed?"DISPUTED":total==Long.parseLong(r.amount())?"SIMULATED_ALLOCATED":total>0?"PARTIAL":"UNFUNDED");out.put("syntheticBookingStatus",booking.isPresent()?"SIMULATED_CONFIRMED":"NOT_CONFIRMED");out.put("synthetic",true);out.put("paymentVerified",false);out.put("bookingConfirmed",false);out.put("bookingId",booking.map(UUID::toString).orElse(null));out.put("label","SYNTHETIC TEST — NO REAL MONEY");return out;}
 Map<String,Object> exceptionView(UUID v,UUID id){var e=db.exceptionDetail(Map.of("id",id,"v",v));var out=new LinkedHashMap<String,Object>();for(String k:List.of("exception_id","kind","state","revision","due_at"))out.put(k,k.equals("due_at")?instant(e.get(k)).toString():e.get(k).toString());out.put("overdue",instant(e.get("due_at")).isBefore(bank.now()));out.put("assignedTo",Objects.toString(e.get("assigned_to"),"UNASSIGNED"));return out;}
 Object read(UUID a,UUID v,UUID id,boolean exceptions){return tx.execute(s->{permit(a,v,exceptions?"bank.synthetic.resolve":"bank.synthetic.credit.read");bank.audit(a,null,"FINANCIAL_READ","SYNTHETIC_ONLY");if(id!=null)return exceptions?exceptionView(v,id):creditView(v,id);String pk=exceptions?"exception_id":"credit_id";return (exceptions?db.exceptionIds(Map.of("v",v)):db.creditIds(Map.of("v",v))).stream().map(r->exceptions?exceptionView(v,(UUID)r.get(pk)):creditView(v,(UUID)r.get(pk))).toList();});}
}
